function recoveryRace(RecoveryEnvironment $r,string $action,string $mode):array {
    global $runtime;$d=$action==='request'?null:$r->delivery();$config=['mysql'=>$r->e->mysql,'socket'=>getenv('SOSECURITY_TEST_MYSQL_SOCKET'),'directory'=>$r->e->directory,'database'=>$r->e->directory.'/registration.sqlite','time'=>$r->e->clock->time,'mfa'=>$r->factor!==null,'password'=>$r->password,'selector'=>$d===null?'':$d->selector(),'token'=>$d===null?'':$d->notice()->token(),'recovery_code'=>$r->codes[0] ?? '','pause'=>$mode==='parallel'?'':$mode,'ready'=>$r->e->directory.'/ready'];$path=$r->e->directory.'/race.json';file_put_contents($path,json_encode($config));chmod($path,0600);
    $command='python3 '.escapeshellarg(__DIR__.'/account_recovery_race.py').' '.escapeshellarg($runtime).' '.escapeshellarg($path).' '.escapeshellarg($action).' '.escapeshellarg($mode);$spec=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']];$process=proc_open($command,$spec,$pipes);fclose($pipes[0]);$output=stream_get_contents($pipes[1]);$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($process);unlink($path);if(file_exists($config['ready'])){unlink($config['ready']);}if($status!==0){throw new RuntimeException('Owned recovery race failed: '.$output.$errors);}return json_decode($output,true);
